    buildWorkRevisionEvent({ eventId: `fixture:${kind}`, now: fixtureNow, revision: {
      kind, id: kind, scopeId: "scope", revision: 1, predecessor: null, contentDigest: fixtureDigest,
      parent: null, dependencies: [], ownerId: "fixture-owner", permittedEffects: [], policy: null, ...patch,
    } });
