  const intent = revision("goal", { parent: fixtureRevisionRef(scope) });
  const obligation = revision("obligation", { parent: fixtureRevisionRef(intent), policy: fixtureRevisionRef(policy) });
  const binding = { intent: fixtureRevisionRef(intent), obligation: fixtureRevisionRef(obligation),
    artifact: fixtureRevisionRef(artifact), policy: fixtureRevisionRef(policy) };
  const snapshot = buildWorkSnapshotEvent({ eventId: "fixture:snapshot", now: fixtureNow, snapshot: {
    snapshotId: "fixture-selected", scope: fixtureRevisionRef(scope),
    revisions: [policy, artifact, intent, obligation].map(fixtureRevisionRef), bindings: [binding],
  } });
