export type LayoutRevisionChange = FixtureRevisionChange | "snapshot";
/** Closed successor worlds; rebase the actual scope -> goal -> node -> obligation chain. */
export function layoutSuccessorFixture(primary: LayoutRevisionChange) {
  if (!["scope", "intent", "obligation", "artifact", "policy", "snapshot"].includes(primary)) throw new TypeError("unknown layout successor world");
  const base = layoutFixture(), current = { scope: base.scope, goal: base.goal, intent: base.intent, obligation: base.obligation, artifact: base.artifact, policy: base.policy };
  const successor = (name: keyof typeof current, patch: Partial<Omit<WorkRevision, "digest">> = {}) => {
    const prior = base[name], { digest: _, ...body } = mutableFixture(prior.payload.revision);
    return buildWorkRevisionEvent({ eventId: `layout:${primary}:${name}:2`, now: fixtureNow, revision: {
      ...body, revision: 2, predecessor: fixtureRevisionRef(prior), contentDigest: name === primary ? "c".repeat(64) : body.contentDigest, ...patch,
    } });
  };
  if (primary === "scope") { current.scope = successor("scope"); current.goal = successor("goal", { parent: fixtureRevisionRef(current.scope) }); }
  if (primary === "scope" || primary === "intent") current.intent = successor("intent", { parent: fixtureRevisionRef(current.goal) });
  if (primary === "artifact") current.artifact = successor("artifact");
  if (primary === "policy") current.policy = successor("policy");
  if (!["artifact", "snapshot"].includes(primary)) current.obligation = successor("obligation", { parent: fixtureRevisionRef(current.intent), policy: fixtureRevisionRef(current.policy) });
  const binding = { intent: fixtureRevisionRef(current.intent), obligation: fixtureRevisionRef(current.obligation), artifact: fixtureRevisionRef(current.artifact), policy: fixtureRevisionRef(current.policy) };
  const snapshot = buildWorkSnapshotEvent({ eventId: `layout:${primary}:snapshot`, now: fixtureNow, snapshot: {
    snapshotId: `layout:${primary}:selected`, scope: fixtureRevisionRef(current.scope), revisions: [current.policy, current.artifact, current.goal, current.intent, current.obligation].map(fixtureRevisionRef), bindings: [binding],
  } });
  const occurrences = base.occurrences.map((e, i) => buildWorkOccurrenceEvent({ eventId: `layout:${primary}:observation:${i}`, now: fixtureNow, payload: {
    ...e.payload, scope: fixtureRevisionRef(current.scope), obligation: binding.obligation, artifact: binding.artifact,
  } }));
  const claim = buildWorkAcceptanceEvent({ eventId: `layout:${primary}:claim`, now: fixtureNow, payload: { authorityId: "layout-controller", binding: {
    ...binding, scope: fixtureRevisionRef(current.scope), snapshot: { id: snapshot.payload.snapshot.snapshotId, digest: snapshot.payload.snapshot.digest },
    artifactDigest: current.artifact.payload.revision.contentDigest, evidence: [{ id: `layout:${primary}:proof`, digest: "d".repeat(64), event: fixtureEventRef(occurrences[0]) }],
  } } });
  const changes = (Object.keys(current) as (keyof typeof current)[]).filter(k => current[k] !== base[k]);
  return { base, current, changes, snapshot, occurrences, claim, events: [...base.events, ...changes.map(k => current[k]), snapshot, ...occurrences, claim] };
}
export function layoutSuccessorAuthority(primary: LayoutRevisionChange): WorkProjectionContext {
  const expected = layoutSuccessorFixture(primary), ctx = layoutAuthority();
  ctx.selectedSnapshot = { snapshot: mutableFixture(expected.claim.payload.binding.snapshot), event: fixtureEventRef(expected.snapshot) };
  ctx.authority!.snapshot = { id: `layout-fixture-authority:${primary}`, digest: "e".repeat(64) };
  ctx.authority!.decisions.push({ receiptId: `layout-receipt:${primary}`, authorityId: "layout-controller", claim: fixtureEventRef(expected.claim), binding: mutableFixture(expected.claim.payload.binding), decision: "accept" });
  if (primary === "artifact") ctx.authority!.availability.push({ kind: "artifact", id: "layout-image", digest: "c".repeat(64), available: true });
  ctx.authority!.availability.push({ kind: "evidence", id: `layout:${primary}:proof`, digest: "d".repeat(64), available: true });
  return ctx;
}

